window.SLOWNIK = [{"t": "ARiMR", "s": ["agencja restrukturyzacji", "agencji restrukturyzacji", "arimr"], "d": "Agencja Restrukturyzacji i Modernizacji Rolnictwa: urząd wypłacający dopłaty bezpośrednie i prowadzący rejestr zwierząt gospodarskich (IRZ). Rolnik zgłasza tam m.in. urodzenia, przemieszczenia i ubój zwierząt."}, {"t": "AdBlue", "s": ["adblue"], "d": "Wodny roztwór mocznika wtryskiwany do spalin w układzie SCR, obniżający emisję tlenków azotu w nowoczesnych ciągnikach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/2015_Audi_Q3_2.0_TDI_quattro_Facelift_Typ_8U_Tankeinfuellstutzen_AdBlue.jpg/330px-2015_Audi_Q3_2.0_TDI_quattro_Facelift_Typ_8U_Tankeinfuellstutzen_AdBlue.jpg", "w": "AdBlue"}, {"t": "Chroniona Nazwa Pochodzenia / Oznaczenie Geograficzne", "s": ["chronion"], "d": "Unijne oznaczenia jakości żywności: ChNP – cały proces produkcji w danym regionie; ChOG – przynajmniej jeden etap związany z regionem."}, {"t": "DJP", "s": ["djp", "jednostek przeliczeniow", "jednostka przeliczeniow"], "d": "Duża jednostka przeliczeniowa inwentarza – umowna jednostka równa krowie o masie 500 kg; służy do przeliczania obsady zwierząt i potrzebnej pojemności zbiorników na nawozy naturalne."}, {"t": "EUROP", "s": ["europ"], "d": "Unijny system klasyfikacji tusz zwierząt rzeźnych według umięśnienia (klasy od E - najlepsza, przez U, R, O, do P) i otłuszczenia. Od klasy zależy cena płacona rolnikowi."}, {"t": "GAEC", "s": ["gaec"], "d": "Normy dobrej kultury rolnej zgodnej z ochroną środowiska, których rolnik musi przestrzegać, aby otrzymać dopłaty unijne (np. GAEC 2 chroni tereny podmokłe i torfowiska)."}, {"t": "MMA", "s": ["bezmleczno", "mma"], "d": "Zespół bezmleczności poporodowej u loch (mastitis-metritis-agalactia): zapalenie wymienia i macicy oraz brak mleka w pierwszych dniach po porodzie. Prosięta głodują i giną."}, {"t": "NPK", "s": ["npk", "polifosk"], "d": "Skrót trzech głównych składników nawozowych: azot (N), fosfor (P) i potas (K). Nawóz wieloskładnikowy NPK to np. Polifoska."}, {"t": "OSN", "s": ["osn"], "d": "Obszary szczególnie narażone na zanieczyszczenie azotanami pochodzenia rolniczego. Obowiązują tam ostrzejsze wymagania dotyczące przechowywania i stosowania nawozów naturalnych."}, {"t": "PIORiN", "s": ["inspekcja ochrony roślin", "inspekcji ochrony roślin", "piorin"], "d": "Państwowa Inspekcja Ochrony Roślin i Nasiennictwa – kontroluje obrót i stosowanie środków ochrony roślin oraz jakość materiału siewnego."}, {"t": "Powiatowy Lekarz Weterynarii", "s": ["lekarz weterynarii", "lekarza weterynarii"], "d": "Urzędowy lekarz weterynarii nadzorujący zdrowie zwierząt w powiecie; jemu zgłasza się podejrzenia chorób zakaźnych i uboje w strefach zagrożonych."}, {"t": "TMR", "s": ["tmr"], "d": "Total Mixed Ration – system żywienia bydła, w którym wszystkie pasze (objętościowe, treściwe, dodatki) są dokładnie wymieszane w wozie paszowym i podawane jako jedna pełnoporcjowa dawka."}, {"t": "WOM", "s": ["wałek odbioru mocy", "wałka odbioru mocy", "wom "], "d": "Wałek odbioru mocy – wałek z tyłu (lub przodu) ciągnika przekazujący napęd silnika do maszyn, np. kosiarek, bron aktywnych.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/18/TractorPTOshaftMay04.jpg/330px-TractorPTOshaftMay04.jpg", "w": "Wał odbioru mocy"}, {"t": "Zwykła Dobra Praktyka Rolnicza", "s": ["dobra praktyka", "dobrej praktyk", "dobrej praktyki", "dobrą praktyką", "zdpr"], "d": "Zbiór podstawowych zasad gospodarowania zgodnego z prawem i ochroną środowiska (nawożenie, dobrostan zwierząt, ochrona wód), którego przestrzegania wymagano w programach rolnośrodowiskowych."}, {"t": "aberdeen angus", "s": ["angus"], "d": "Szkocka rasa bydła mięsnego, bezrożna, najczęściej czarna. Ceniona za marmurkowate mięso i łatwe porody.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/AngusCattle.jpg/330px-AngusCattle.jpg", "w": "Aberdeen angus"}, {"t": "adiuwant", "s": ["adiuwant"], "d": "Substancja pomocnicza dodawana do cieczy opryskowej, która poprawia przyczepność i działanie środka ochrony roślin."}, {"t": "agregat uprawowy", "s": ["agregat"], "d": "Zestaw kilku narzędzi (np. kultywator, brona, wał) połączonych w jedną maszynę, który w jednym przejeździe przygotowuje glebę do siewu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Belarus-Minsk-Agriculture_Expo-Machinery-6.jpg/330px-Belarus-Minsk-Agriculture_Expo-Machinery-6.jpg", "w": "Agregat uprawowy"}, {"t": "balot (bela)", "s": ["balot", "bel ", "bela", "bele"], "d": "Sprasowana porcja siana, słomy lub sianokiszonki – cylindryczna (z prasy zwijającej) lub sześcienna (z prasy kostkującej); do załadunku służy chwytak.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Chwytak_do_bel.jpg/330px-Chwytak_do_bel.jpg", "w": "Chwytak do bel"}, {"t": "blokada mechanizmu różnicowego", "s": ["różnicow"], "d": "Połączenie obu kół napędowych w sztywno obracającą się całość, gdy jedno z nich buksuje (np. przy orce); nie wolno jej używać przy szybkiej jeździe.", "img": "https://upload.wikimedia.org/wikipedia/commons/6/61/Differential_free.png", "w": "Mechanizm różnicowy"}, {"t": "bobik", "s": ["bobik"], "d": "Odmiana bobu uprawiana na nasiona jako roślina pastewna, należy do roślin strączkowych grubonasiennych. Wzbogaca glebę w azot i jest dobrym przedplonem dla zbóż.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Illustration_Vicia_faba1.jpg/330px-Illustration_Vicia_faba1.jpg", "w": "Wyka bób"}, {"t": "brojler", "s": ["brojler"], "d": "Kurczę (lub inne ptactwo) szybko rosnącej linii mięsnej, tuczone ok. 6 tygodni."}, {"t": "brona", "s": ["bron", "bron ", "brona", "bronow", "brony", "broną", "bronę"], "d": "Narzędzie z zębami lub talerzami ciągnięte po polu w celu rozkruszenia brył, wyrównania gleby i zniszczenia małych chwastów. Bronowanie wykonuje się też pielęgnacyjnie w rosnących zbożach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Handeg.jpg/330px-Handeg.jpg", "w": "Brona (rolnictwo)"}, {"t": "brona talerzowa", "s": ["talerzow"], "d": "Narzędzie z rzędami wklęsłych, obracających się talerzy, które tną i mieszają glebę z resztkami roślinnymi; używana m.in. zamiast podorywki na ściernisku.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Handeg.jpg/330px-Handeg.jpg", "w": "Brona talerzowa"}, {"t": "brona wirnikowa", "s": ["wirnikow"], "d": "Brona aktywna napędzana od WOM ciągnika; zęby na pionowych wirnikach rozdrabniają glebę przed siewem."}, {"t": "chaber bławatek", "s": ["bławat", "chaber"], "d": "Chwast zbożowy o błękitnych kwiatostanach typu koszyczek; dawniej bardzo pospolity w polach zbóż.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Centaureacyanus.jpg/330px-Centaureacyanus.jpg", "w": "Chaber bławatek"}, {"t": "charolaise", "s": ["charolais"], "d": "Francuska rasa bydła mięsnego o białokremowej sierści, najbardziej masywna i szybko rosnąca. Nadaje się do intensywnego opasu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Taureau_charolais.jpg/330px-Taureau_charolais.jpg", "w": "Charolaise"}, {"t": "choroba Mareka", "s": ["marek"], "d": "Wirusowa choroba kur powodująca porażenie nerwów i kończyn (typowa pozycja szpagatu), guzy i wyniszczenie. Zapobiega się jej szczepieniem piskląt.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Marek%27s_disease%2C_cutaneous%2C_broiler.jpg/330px-Marek%27s_disease%2C_cutaneous%2C_broiler.jpg", "w": "Choroba Mareka"}, {"t": "choroba motylicza", "s": ["motylic"], "d": "Pasożytnicza choroba bydła i owiec wypasanych na podmokłych łąkach, wywołana przez motylicę wątrobową (płaziniec żyjący w wątrobie). Objawy: wychudzenie, biegunka, obrzęki, niedokrwistość.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Fasciola_hepatica.JPG/330px-Fasciola_hepatica.JPG", "w": "Motylica wątrobowa"}, {"t": "chowacz brukwiaczek", "s": ["chowacz"], "d": "Chrząszcz-ryjkowiec, którego larwy żerują wewnątrz łodyg rzepaku, powodując ich skrzywienie i pękanie."}, {"t": "chowacz czterozębny", "s": ["czterozębn"], "d": "Ryjkowiec, którego larwy drążą korytarze w łodygach i ogonkach liściowych rzepaku.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Ceutorhynchus_pallidactylus_%28Marsham%2C_1802%29_%288427120384%29.png/330px-Ceutorhynchus_pallidactylus_%28Marsham%2C_1802%29_%288427120384%29.png", "w": "Chowacz czterozębny"}, {"t": "chwastnica jednostronna", "s": ["chwastnic"], "d": "Jednoroczny chwast trawiasty o wiechach z jednostronnie ułożonymi kłoskami, typowy dla kukurydzy i upraw okopowych. Lubi ciepło i wschodzi późno wiosną.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Echinochloa_crus-galli_15-p.bot-echi.crugal-26.jpg/330px-Echinochloa_crus-galli_15-p.bot-echi.crugal-26.jpg", "w": "Chwastnica jednostronna"}, {"t": "czarna nóżka", "s": ["czarn"], "d": "Bakteryjna choroba ziemniaka: podstawa łodygi czernieje i gnije, a bulwy ulegają mokrej zgniliźnie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Black_leg_of_potato.jpg/330px-Black_leg_of_potato.jpg", "w": "Czarna nóżka ziemniaka"}, {"t": "czepiec", "s": ["czepc", "czepiec"], "d": "Druga komora żołądka przeżuwaczy o ścianie przypominającej plaster miodu; wspomaga odłykanie pokarmu do przeżuwania.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Stomach_of_a_beef.png/330px-Stomach_of_a_beef.png", "w": "Czepiec (przeżuwacze)"}, {"t": "czerń krzyżowych", "s": ["czerni", "czerń"], "d": "Choroba grzybowa rzepaku i innych kapustowatych: ciemnobrunatne plamy z ciemnym nalotem zarodników na liściach, łodygach i łuszczynach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Alternaria_brassicicola_host_symptoms4.jpg/330px-Alternaria_brassicicola_host_symptoms4.jpg", "w": "Czerń krzyżowych"}, {"t": "decytona", "s": ["dt/ha"], "d": "Jednostka masy równa 100 kg (dawniej kwintal), oznaczana dt. Plony i normy wysiewu w rolnictwie podaje się często w dt/ha."}, {"t": "dekornizacja", "s": ["dekorniz", "zawiązk rog", "zawiązków rog"], "d": "Usuwanie zawiązków rogów u młodych cieląt, aby zwierzęta nie raniły się w stadzie. Wykonuje się ją termicznie (dekornizator gazowy lub elektryczny) lub chemicznie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/29/Dehorned_dairy_cow.jpg/330px-Dehorned_dairy_cow.jpg", "w": "Dekornizacja"}, {"t": "desykacja", "s": ["desykac"], "d": "Chemiczne wysuszenie roślin przed zbiorem (np. strączkowych, rzepaku) środkiem zwanym desykantem, aby przyspieszyć i wyrównać dojrzewanie."}, {"t": "deszczownia", "s": ["deszczown"], "d": "Urządzenie do nawadniania pól przez rozpryskiwanie wody w postaci sztucznego deszczu. Inne sposoby nawadniania to zalewowe, stokowe i podsiąkowe."}, {"t": "dezynsekcja / deratyzacja", "s": ["deratyz", "dezynsekc"], "d": "Dezynsekcja – zwalczanie owadów (np. piórojadów, much); deratyzacja – zwalczanie gryzoni (szczurów, myszy) w budynkach inwentarskich."}, {"t": "drenowanie", "s": ["drenar", "drenow"], "d": "Odwadnianie pola podziemnymi rurkami (drenami) odprowadzającymi nadmiar wody do rowu przez wyloty drenarskie. Brak odpływu w czasie deszczu świadczy o zapchaniu sieci."}, {"t": "drutowce", "s": ["drut owc", "drutow"], "d": "Larwy chrząszczy sprężykowatych, twarde i żółte jak kawałki drutu, żyjące w glebie. Wygryzają korzenie i bulwy ziemniaków, kukurydzy i zbóż.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/ElateridAdLarvae.jpg/330px-ElateridAdLarvae.jpg", "w": "Sprężykowate"}, {"t": "duroc", "s": ["duroc"], "d": "Amerykańska rasa świń o rudej sierści, typu mięsnego, często używana jako komponent ojcowski w krzyżowaniu. Daje mięso dobrej jakości, przerośnięte tłuszczem.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Duroc_Boar_at_7_Months_-_2.jpg/330px-Duroc_Boar_at_7_Months_-_2.jpg", "w": "Duroc (rasa świń)"}, {"t": "dyrektywa azotanowa", "s": ["azotanow"], "d": "Przepis Unii Europejskiej ograniczający stosowanie nawozów azotowych (w tym naturalnych) w celu ochrony wód przed zanieczyszczeniem azotanami – m.in. terminy i dawki nawożenia."}, {"t": "elektryzator", "s": ["elektryzator"], "d": "Urządzenie zasilające ogrodzenie elektryczne (pastuch) na pastwisku; wysyła w drut krótkie impulsy wysokiego napięcia. Dobiera się go do długości ogrodzenia i rodzaju zwierząt.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Electric_fence_01.jpg/330px-Electric_fence_01.jpg", "w": "Elektryczny pastuch"}, {"t": "esparceta", "s": ["esparcet"], "d": "Wieloletnia roślina motylkowata pastewna o różowych kwiatach, dobrze rosnąca na suchych glebach wapiennych. Uprawiana na siano i zielonkę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/93_Onobrychis_sativa_Lmk.jpg/330px-93_Onobrychis_sativa_Lmk.jpg", "w": "Sparceta siewna"}, {"t": "facelia", "s": ["faceli"], "d": "Roślina o niebieskofioletowych kwiatach, szybko rosnąca, uprawiana jako poplon ścierniskowy, nawóz zielony i roślina miododajna. Nie jest spokrewniona z żadną rośliną uprawną, więc nie przenosi ich chorób.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Phacelia_tanacetifolia_RHu_001.JPG/330px-Phacelia_tanacetifolia_RHu_001.JPG", "w": "Facelia błękitna"}, {"t": "faszyna", "s": ["faszyn"], "d": "Wiązki gałęzi (zwykle wikliny) używane do umacniania skarp rowów, brzegów i wałów.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/86/Halbinsel_Warflether_Sand_Weser_%2850670800343%29.jpg/330px-Halbinsel_Warflether_Sand_Weser_%2850670800343%29.jpg", "w": "Faszyna"}, {"t": "fumigacja (fumigant)", "s": ["fumig"], "d": "Zwalczanie szkodników gazem lub parami środka chemicznego w zamkniętej przestrzeni, np. w silosie zbożowym przeciw wołkowi zbożowemu."}, {"t": "fungicyd", "s": ["fungicyd"], "d": "Środek ochrony roślin do zwalczania chorób grzybowych. Inne grupy: herbicydy (chwasty), insektycydy (owady), akarycydy (roztocza), rodentycydy (gryzonie)."}, {"t": "fuzarioza", "s": ["fuzario", "fuzarioz", "mykotoksyn"], "d": "Choroba grzybowa (Fusarium) kłosów zbóż i kolb kukurydzy; porażone, wilgotne ziarno zawiera mykotoksyny – trujące substancje grzybów, groźne dla ludzi i zwierząt.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/Wheat_scab.jpg/330px-Wheat_scab.jpg", "w": "Fuzarioza kłosów zbóż"}, {"t": "giez bydlęcy", "s": ["giez", "gza bydl"], "d": "Mucha, której larwy wędrują pod skórą bydła i tworzą na grzbiecie guzy z otworem oddechowym. Choroba nazywa się gzawicą.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Ox_Warble-fly.png/330px-Ox_Warble-fly.png", "w": "Giez bydlęcy duży"}, {"t": "gniotownik", "s": ["gniotownik"], "d": "Urządzenie zgniatające ziarno między walcami na płatki; zgniecione ziarno owsa lepiej trawią konie."}, {"t": "gnojowica", "s": ["gnojowic"], "d": "Płynny nawóz naturalny z odchodów zwierząt i wody, powstający w oborach i chlewniach bez ściółki. Przechowuje się ją w szczelnych zbiornikach i nie wolno jej rozlewać na zamarzniętą glebę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Sleufkouterbemester.jpg/330px-Sleufkouterbemester.jpg", "w": "Gnojowica"}, {"t": "gnojówka", "s": ["gnojówk"], "d": "Płynny nawóz naturalny – przefermentowany mocz zwierząt z wodą spływającą z obory; przechowuje się go w szczelnych zbiornikach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Sleufkouterbemester.jpg/330px-Sleufkouterbemester.jpg", "w": "Gnojówka"}, {"t": "gorczyca biała", "s": ["gorczyc"], "d": "Roślina z rodziny kapustowatych o szybkim wzroście, uprawiana na nasiona (musztarda) i jako poplon ścierniskowy na nawóz zielony. Nadaje się do późnego siewu po żniwach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Sinapis_alba_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-265.jpg/330px-Sinapis_alba_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-265.jpg", "w": "Gorczyca biała"}, {"t": "gruda", "s": ["gruda", "grudy", "grudą", "grudę"], "d": "Zapalenie skóry pęcin u koni (strupy, pęknięcia), wywołane wilgocią i brudem w stajni lub na pastwisku."}, {"t": "gryka", "s": ["gryce", "gryk", "gryka", "gryki", "grykę"], "d": "Roślina z rodziny rdestowatych (nie trawa), uprawiana na kaszę gryczaną. Świetnie rośnie na glebach lekkich i kwaśnych, a jej kwiaty są cenionym pożytkiem dla pszczół.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c3/Illustration_Fagopyrum_esculentum0_clean.jpg/330px-Illustration_Fagopyrum_esculentum0_clean.jpg", "w": "Gryka zwyczajna"}, {"t": "gęsiostopka", "s": ["gęsiostop"], "d": "Szeroka, trójkątna redliczka na zębie kultywatora, podcinająca chwasty na całej szerokości."}, {"t": "głownia", "s": ["głowni"], "d": "Choroba grzybowa zbóż, w której zamiast ziarna w kłosie powstaje czarna, pyląca masa zarodników. Przenosi się z zakażonym ziarnem siewnym, dlatego ważne jest zaprawianie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Ustilago_nuda_barley%2C_stuifbrand_op_gerst_%283%29.jpg/330px-Ustilago_nuda_barley%2C_stuifbrand_op_gerst_%283%29.jpg", "w": "Głownia pyląca jęczmienia"}, {"t": "głębosz", "s": ["głębosz"], "d": "Głębokie spulchnienie gleby (40–60 cm) głęboszem bez odwracania warstw, w celu rozbicia zbitej podeszwy i poprawy stosunków wodno-powietrznych na glebach ciężkich.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Gleboszowanie.jpg/330px-Gleboszowanie.jpg", "w": "Głęboszowanie"}, {"t": "herbicyd", "s": ["herbicyd"], "d": "Chemiczny środek ochrony roślin służący do zwalczania chwastów. Może działać wybiórczo (tylko na niektóre rośliny) lub niszczyć całą roślinność."}, {"t": "hereford", "s": ["hereford"], "d": "Brytyjska rasa bydła mięsnego o czerwonym umaszczeniu z białą głową, podgardlem, podbrzuszem i końcówką ogona. Bardzo wytrzymała, chętnie utrzymywana na pastwiskach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Hereford_bull_large.jpg/330px-Hereford_bull_large.jpg", "w": "Hereford (rasa bydła)"}, {"t": "holsztyńsko-fryzyjska", "s": ["fryzyjsk", "holstein", "holsztyń"], "d": "Najpopularniejsza na świecie rasa bydła mlecznego, zwykle czarno-biała. Krowy tej rasy dają najwięcej mleka ze wszystkich ras.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/HF_in_der_Rh%C3%B6n_auf_der_Weide.jpg/330px-HF_in_der_Rh%C3%B6n_auf_der_Weide.jpg", "w": "Holsztyno-fryzyjska rasa bydła"}, {"t": "insektycyd", "s": ["insektycyd"], "d": "Środek owadobójczy stosowany przeciwko szkodnikom, takim jak mszyce, stonka czy omacnica. Środki o działaniu układowym wnikają do soków rośliny i działają na owady ssące."}, {"t": "integrowana ochrona roślin", "s": ["integrowan"], "d": "Sposób ochrony roślin, w którym chemię stosuje się dopiero wtedy, gdy metody agrotechniczne, biologiczne i mechaniczne nie wystarczają; obowiązkowy w UE od 2014 r."}, {"t": "jałówka", "s": ["jałów", "jałówk"], "d": "Młoda samica bydła, która jeszcze się nie cieliła. Po pierwszym wycieleniu staje się krową."}, {"t": "jednostka siewna", "s": ["jednostek siewn", "jednostka siewn", "jednostki siewn"], "d": "Opakowanie nasion o określonej liczbie ziaren (np. 50 tys. nasion kukurydzy lub 100 tys. nasion buraka). Ułatwia obliczanie ilości materiału siewnego przy planowanej obsadzie roślin na hektar."}, {"t": "jersey", "s": ["jersey"], "d": "Niewielka rasa bydła mlecznego z wyspy Jersey, o jasnobrązowym umaszczeniu. Daje mleko o bardzo wysokiej zawartości tłuszczu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Walworth_Gate_010.jpg/330px-Walworth_Gate_010.jpg", "w": "Jersey (rasa bydła)"}, {"t": "ketoza", "s": ["ketoz"], "d": "Choroba przemiany materii u krów wysokomlecznych, zwykle po wycieleniu; objawy to brak apetytu, spadek mleczności, twardy kał i zapach acetonu w wydychanym powietrzu."}, {"t": "kiszonka", "s": ["kiszon", "kiszonk"], "d": "Pasza konserwowana przez zakiszanie (fermentację mlekową bez dostępu powietrza), np. kiszonka z kukurydzy. Pasza objętościowa soczysta; nadaje się do skarmiania po ok. 6 tygodniach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Cattle_eating_corn_silage.jpg/330px-Cattle_eating_corn_silage.jpg", "w": "Kiszonka"}, {"t": "klasa bonitacyjna", "s": ["bonitac"], "d": "Ocena jakości gleby w skali od I (najlepsza) do VI (najsłabsza), wpisywana do ewidencji gruntów. Klasa V to słabe gleby pod żyto i seradelę."}, {"t": "klasa wczesności FAO", "s": ["fao"], "d": "Liczba (np. FAO 240) określająca wczesność odmiany kukurydzy; im wyższa, tym dłuższy okres wegetacji i więcej ciepła potrzebuje odmiana."}, {"t": "klepisko", "s": ["bębna młóc", "klepisk", "omłotow"], "d": "Wygięta kratowa część zespołu młócącego, nad którą obraca się bęben; ziarno wykruszane jest w szczelinie omłotowej między bębnem a klepiskiem. Zmniejszenie szczeliny poprawia wymłócenie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/Bizon_ZO56_01.jpg/330px-Bizon_ZO56_01.jpg", "w": "Kombajn zbożowy"}, {"t": "kolczyk (identyfikacja zwierząt)", "s": ["kolczyk"], "d": "Plastikowy znacznik z numerem zakładany na ucho bydła, owiec, kóz i świń do identyfikacji; duplikat zgubionego zamawia się w biurze powiatowym ARiMR."}, {"t": "komosa biała", "s": ["komos"], "d": "Jeden z najpospolitszych chwastów dwuliściennych w uprawach okopowych i jarych (potocznie lebioda). Liście pokryte białym, mączystym nalotem; jedna roślina daje tysiące nasion.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fb/Chenopodium_album_Sturm27.jpg/330px-Chenopodium_album_Sturm27.jpg", "w": "Komosa biała"}, {"t": "kompleks przydatności rolniczej gleb", "s": ["kompleks"], "d": "Grupa gleb o podobnych możliwościach uprawy, nazwana od zboża wskaźnikowego, np. kompleks pszenny bardzo dobry lub żytni słaby (gleby lekkie, piaszczyste – żyto, łubin, seradela)."}, {"t": "kompleks żytni", "s": ["kompleks żytn", "kompleksu żytn"], "d": "Kategoria przydatności rolniczej gleb lekkich (piaszczystych), na których najlepiej udaje się żyto, ziemniaki i owies; dzieli się na bardzo dobry, dobry, słaby i bardzo słaby."}, {"t": "koniczyna czerwona", "s": ["koniczyn"], "d": "Roślina motylkowata pastewna (koniczyna łąkowa), wysiewana często jako wsiewka w zboża jare. Uprawiana na zielonkę i siano, zostawia w glebie dużo azotu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Cleaned-Illustration_Trifolium_pratense.jpg/330px-Cleaned-Illustration_Trifolium_pratense.jpg", "w": "Koniczyna łąkowa"}, {"t": "kopiec", "s": ["kopc", "kopiec"], "d": "Tradycyjny sposób przechowywania ziemniaków lub buraków: pryzma przykryta słomą i ziemią. Trudno w nim kontrolować temperaturę i wilgotność.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Gerooide_aardappels.JPG/330px-Gerooide_aardappels.JPG", "w": "Kopiec (rolnictwo)"}, {"t": "kosiarka rotacyjna", "s": ["kosiark", "rotacyjn"], "d": "Kosiarka, w której trawę ścinają szybko obracające się bębny lub tarcze z nożykami. Wysokość koszenia reguluje się m.in. pierścieniami dystansowymi.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Cutting_the_grass_while_its_dry.jpg/330px-Cutting_the_grass_while_its_dry.jpg", "w": "Kosiarka"}, {"t": "koza burska", "s": ["bursk"], "d": "Południowoafrykańska rasa kóz mięsnych – biały tułów z brązową głową i szyją.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Boerbok.jpg/330px-Boerbok.jpg", "w": "Koza burska"}, {"t": "koza saaneńska", "s": ["saaneńsk"], "d": "Szwajcarska biała rasa kóz, najwydajniejsza mlecznie na świecie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Saanenziege.jpg/330px-Saanenziege.jpg", "w": "Koza saaneńska"}, {"t": "koń huculski", "s": ["hucul"], "d": "Mała, wytrzymała prymitywna rasa koni górskich z Karpat, objęta programem ochrony; paszporty wydaje Polski Związek Hodowców Koni.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/2_ogiery_huculskie_1.jpg/330px-2_ogiery_huculskie_1.jpg", "w": "Koń huculski"}, {"t": "koń sztumski", "s": ["sztumsk"], "d": "Polska rasa ciężkich koni zimnokrwistych z okolic Sztumu na Pomorzu, dawniej używana do prac rolnych.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Weidegang_Kaltbl%C3%BCter.JPG/330px-Weidegang_Kaltbl%C3%BCter.JPG", "w": "Koń zimnokrwisty"}, {"t": "koń zimnokrwisty", "s": ["zimnokrwist"], "d": "Ciężki, masywny typ konia o spokojnym temperamencie, hodowany do pracy w polu i w transporcie (np. konie sztumskie, sokólskie).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Weidegang_Kaltbl%C3%BCter.JPG/330px-Weidegang_Kaltbl%C3%BCter.JPG", "w": "Koń zimnokrwisty"}, {"t": "krój tarczowy", "s": ["kroju tarczow", "krój tarczow"], "d": "Obracająca się tarcza umieszczona przed korpusem pługa, która pionowo nacina skibę i ułatwia czystą orkę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Old_plough_schema.svg/langpl-330px-Old_plough_schema.svg.png", "w": "Pług"}, {"t": "księgi", "s": ["księg"], "d": "Trzecia komora żołądka przeżuwaczy, z licznymi fałdami jak kartki książki, w której pokarm jest odwadniany i rozcierany."}, {"t": "kultywator", "s": ["gruber", "kultywator"], "d": "Narzędzie z zębami (łapami) spulchniające glebę bez jej odwracania, stosowane po podorywce lub przed siewem. Gruber to ciężki kultywator, który może zastąpić podorywkę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Tandeg.jpg/330px-Tandeg.jpg", "w": "Kultywator"}, {"t": "kultywator ścierniskowy", "s": ["ścierniskow"], "d": "Ciężki kultywator (gruber) do uprawy ścierniska po żniwach zamiast podorywki; miesza resztki pożniwne z glebą.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Tandeg.jpg/330px-Tandeg.jpg", "w": "Kultywator"}, {"t": "kwasica żwacza", "s": ["kwasic"], "d": "Zaburzenie trawienia u przeżuwaczy spowodowane nadmiarem pasz treściwych (zbóż), które gwałtownie zakwaszają treść żwacza."}, {"t": "kąkol polny", "s": ["kąkol"], "d": "Dawniej pospolity chwast zbóż o różowofioletowych kwiatach i trujących nasionach. Dziś rzadki dzięki czyszczeniu materiału siewnego.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Illustration_Agrostemma_githago1.jpg/330px-Illustration_Agrostemma_githago1.jpg", "w": "Kąkol polny"}, {"t": "kłąb", "s": ["kłąb", "kłębie", "kłębu"], "d": "Wyniosłość grzbietu konia (bydła) za szyją, między łopatkami; od kłębu mierzy się wysokość zwierzęcia.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Withers.jpg/330px-Withers.jpg", "w": "Kłąb (weterynaria)"}, {"t": "leghorn", "s": ["leghorn"], "d": "Lekka rasa kur typu nieśnego pochodząca z Włoch, najczęściej biała. Znosi dużo jaj o białej skorupie i jest podstawą wielu mieszańców towarowych.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/Leghorn.jpg/330px-Leghorn.jpg", "w": "Leghorn"}, {"t": "lemiesz", "s": ["lemiesz"], "d": "Dolna, tnąca część korpusu pługa, która podcina skibę od dołu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Old_plough_schema.svg/langpl-330px-Old_plough_schema.svg.png", "w": "Lemiesz"}, {"t": "limousine", "s": ["limousin", "limusin"], "d": "Francuska rasa bydła mięsnego o jednolitym czerwono-złotym umaszczeniu. Daje dużo chudego mięsa i dobrze znosi chów pastwiskowy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Limousinedeface.JPG/330px-Limousinedeface.JPG", "w": "Limousine"}, {"t": "lizawka", "s": ["lizaw"], "d": "Twarda kostka soli z dodatkiem składników mineralnych, którą zwierzęta liżą, uzupełniając sód i mikroelementy."}, {"t": "locha", "s": ["loch", "loch ", "locha", "lochy", "lochą", "lochę"], "d": "Dorosła samica świni, która już się prosiła (rodziła). Młoda samica przed pierwszym porodem to loszka, a samiec rozpłodowy to knur.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Sow_with_piglet.jpg/330px-Sow_with_piglet.jpg", "w": "Świnia domowa"}, {"t": "lucerna", "s": ["lucern"], "d": "Wieloletnia roślina motylkowata drobnonasienna o bardzo głębokich korzeniach, dająca białkową paszę (siano, zielonkę). Wymaga gleb żyznych i odczynu zbliżonego do obojętnego.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Illustration_Medicago_sativa1.jpg/330px-Illustration_Medicago_sativa1.jpg", "w": "Lucerna siewna"}, {"t": "makuchy", "s": ["makuch"], "d": "Pozostałość po wytłoczeniu oleju z nasion (np. rzepaku), bogata w białko i tłuszcz. Pasza treściwa białkowa dla bydła i świń.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/Collse_Watermolen_oliekoeken.jpg/330px-Collse_Watermolen_oliekoeken.jpg", "w": "Makuch"}, {"t": "materiał siewny kwalifikowany", "s": ["elitarn", "kwalifikow"], "d": "Nasiona o urzędowo potwierdzonej czystości, zdolności kiełkowania i zdrowotności. Kategorie: elitarny (bazowy, przedbazowy) i kwalifikowany (C1, C2)."}, {"t": "melioracja (rów melioracyjny)", "s": ["melioracj", "melioracyj"], "d": "Zabiegi regulujące stosunki wodne gleby: odwadnianie (rowy, dreny) lub nawadnianie. Rów melioracyjny musi być wykaszany, by zachować przepustowość."}, {"t": "merynos", "s": ["merynos"], "d": "Rasa owiec hodowana głównie dla bardzo cienkiej, wysokiej jakości wełny. Merynos polski to krajowa odmiana tej rasy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Champion_Merino_ram_%281905%29.jpg/330px-Champion_Merino_ram_%281905%29.jpg", "w": "Merynosy"}, {"t": "mieszanka pełnoporcjowa", "s": ["pełnoporcjow"], "d": "Pasza treściwa zawierająca wszystkie składniki pokarmowe w odpowiednich proporcjach, którą można skarmiać jako jedyną paszę (np. dla świń lub drobiu). Mieszanka uzupełniająca tylko dopełnia inne pasze."}, {"t": "miotła zbożowa", "s": ["miotł", "miotła zbożow", "miotły zbożow", "miotłę zbożow"], "d": "Trawa będąca uciążliwym chwastem jednoliściennym w zbożach ozimych, zwłaszcza w życie. Kiełkuje jesienią razem ze zbożem i konkuruje z nim o światło i wodę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Apera_spica-venti_sl10.jpg/330px-Apera_spica-venti_sl10.jpg", "w": "Miotła zbożowa"}, {"t": "międzyplon", "s": ["międzyplon"], "d": "Roślina uprawiana między dwoma plonami głównymi (np. gorczyca po żniwach), chroniąca glebę przed erozją i wzbogacająca ją w próchnicę."}, {"t": "mklik mączny", "s": ["mklik"], "d": "Motyl, którego gąsienice żerują w mące, kaszach i ziarnie, sklejając je przędzą. Szkodnik magazynów i młynów.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/25/Ephestia_kuehniella_male_dorsal.jpg/330px-Ephestia_kuehniella_male_dorsal.jpg", "w": "Mklik mączny"}, {"t": "mocznik", "s": ["moczni", "mocznik"], "d": "Najbardziej skoncentrowany stały nawóz azotowy (46% N), działający wolniej od saletry; jedyny nawóz azotowy stosowany też dolistnie. Mocznik pastewny podaje się przeżuwaczom w ściśle ograniczonej dawce.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Harnstoff.svg/langpl-330px-Harnstoff.svg.png", "w": "Mocznik"}, {"t": "mszyce", "s": ["mszyc"], "d": "Drobne owady wysysające soki z roślin, występujące w dużych koloniach na liściach i kłosach. Osłabiają rośliny i przenoszą choroby wirusowe; zwalcza się je insektycydami.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Aphididae_%28aka%29.jpg/330px-Aphididae_%28aka%29.jpg", "w": "Mszyce"}, {"t": "mączka fosforytowa", "s": ["fosforyt"], "d": "Zmielona skała fosforytowa, wolno działający naturalny nawóz fosforowy dopuszczony w rolnictwie ekologicznym.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/Apatite.jpg/330px-Apatite.jpg", "w": "Fosforyty"}, {"t": "mączniak prawdziwy", "s": ["mączniak"], "d": "Choroba grzybowa, która tworzy na liściach i pochwach liściowych biały, mączysty, przypominający watę nalot grzybni. Atakuje zboża, buraki, ogórki i wiele innych roślin.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Hordeum_vulgare_Erysiphe_graminis_f._hordei_%281%29.jpg/330px-Hordeum_vulgare_Erysiphe_graminis_f._hordei_%281%29.jpg", "w": "Mączniak prawdziwy zbóż i traw"}, {"t": "mątwik ziemniaczany", "s": ["mątwik"], "d": "Mikroskopijny nicień glebowy pasożytujący na korzeniach ziemniaka; jego cysty przetrwają w glebie wiele lat, jest szkodnikiem kwarantannowym.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/PotatoNematodeCysts.jpg/330px-PotatoNematodeCysts.jpg", "w": "Mątwik ziemniaczany"}, {"t": "młóto", "s": ["młót", "młóta", "młóto"], "d": "Pozostałość po słodzie z produkcji piwa w browarze, używana jako pasza dla bydła. Zawiera sporo białka i włókna.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Wysyp_m%C5%82%C3%B3ta.jpg/330px-Wysyp_m%C5%82%C3%B3ta.jpg", "w": "Młóto"}, {"t": "nawożenie pogłówne", "s": ["pogłówn"], "d": "Nawożenie wykonywane na rosnące już rośliny (po wschodach), w przeciwieństwie do przedsiewnego. Tak stosuje się głównie szybko działające nawozy azotowe."}, {"t": "obora uwięziowa / wolnostanowiskowa", "s": ["stanowiskow", "uwięzi", "wolnostanowisk"], "d": "Obora uwięziowa – krowy stoją przywiązane na stanowiskach; wolnostanowiskowa – poruszają się swobodnie, co lepiej zapewnia dobrostan (zwłaszcza na głębokiej ściółce)."}, {"t": "obornik", "s": ["obornik"], "d": "Nawóz naturalny będący mieszaniną odchodów zwierząt i ściółki (słomy). Stosuje się go najczęściej pod rośliny okopowe i kukurydzę, w dawce do 170 kg azotu na hektar rocznie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Miststreuer_im_Mostviertel.jpg/330px-Miststreuer_im_Mostviertel.jpg", "w": "Obornik"}, {"t": "obszar zapowietrzony", "s": ["zapowietrz"], "d": "Teren wokół ogniska choroby zakaźnej zwierząt (np. ASF), na którym obowiązują nakazy i zakazy, np. zgłaszanie każdego uboju Powiatowemu Lekarzowi Weterynarii."}, {"t": "ochwat", "s": ["ochwat"], "d": "Bolesne zapalenie tworzywa kopytowego u koni (i racic u bydła), często po przekarmieniu ziarnem lub młodą zielonką; koń odciąża chore kopyta. Mięśniochwat to inna choroba – porażenie mięśni zadu po pracy następującej po kilkudniowym odpoczynku z pełnym żywieniem.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Laminitic.jpg/330px-Laminitic.jpg", "w": "Ochwat"}, {"t": "odczyn gleby", "s": ["odczyn"], "d": "Kwasowość gleby wyrażona w pH: poniżej 6,5 gleba kwaśna, 6,6–7,0 obojętna, powyżej 7,2 zasadowa. Kwaśne gleby wapnuje się."}, {"t": "odkładnica", "s": ["odkładnic"], "d": "Zakrzywiona część korpusu pługa, która odwraca i kruszy skibę odciętą przez lemiesz. Typy: cylindryczna, kulturalna, półśrubowa, śrubowa, ażurowa.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Old_plough_schema.svg/langpl-330px-Old_plough_schema.svg.png", "w": "Pług"}, {"t": "odsadzenie", "s": ["odsadz"], "d": "Oddzielenie młodych (prosiąt, cieląt, źrebiąt) od matki i zakończenie karmienia mlekiem."}, {"t": "okres karencji", "s": ["karencj", "prewencj"], "d": "Karencja – minimalny czas od ostatniego oprysku do zbioru, by plon był bezpieczny do spożycia. Prewencja – czas po zabiegu, w którym ludzie i zwierzęta (zwłaszcza pszczoły) nie mogą mieć kontaktu z opryskaną uprawą."}, {"t": "omacnica prosowianka", "s": ["omacnic"], "d": "Motyl, którego gąsienice wgryzają się w łodygi i kolby kukurydzy, powodując łamanie roślin i straty plonu. Najgroźniejszy szkodnik kukurydzy w Polsce.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/Ostrinia_nubilalis01.jpg/330px-Ostrinia_nubilalis01.jpg", "w": "Przezierka prosowianka"}, {"t": "oproszenie (wyproszenie)", "s": ["oprosz", "wyprosi"], "d": "Poród u świni. Częstotliwość oproszeń – liczba miotów od jednej lochy w roku (ok. 2,2–2,3)."}, {"t": "opryskiwacz", "s": ["opryskiwacz"], "d": "Maszyna rozpylająca ciecz ze środkiem ochrony roślin lub nawozem na pole przez rozpylacze zamontowane na belce polowej. Wymaga kalibracji i okresowego badania technicznego.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Gedragen_spuitmachine_open.jpg/330px-Gedragen_spuitmachine_open.jpg", "w": "Opryskiwacz"}, {"t": "orka siewna", "s": ["orka siewn", "orki siewn", "orkę siewn", "siewn"], "d": "Średnio głęboka orka (ok. 18–25 cm) wykonywana przed siewem rośliny, zwykle ozimin. Orka odwrotka to płytka orka wiosenna na glebach ciężkich.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Fran%C3%A7ois-Andr%C3%A9_Vincent_-_La_Le%C3%A7on_de_labourage.gif/330px-Fran%C3%A7ois-Andr%C3%A9_Vincent_-_La_Le%C3%A7on_de_labourage.gif", "w": "Orka (rolnictwo)"}, {"t": "ostrożeń polny", "s": ["ostroż"], "d": "Wieloletni, kolczasty chwast o bardzo głębokim systemie korzeniowym i fioletowych kwiatach. Odrasta z odcinków korzeni, przez co jest trudny do zwalczenia.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Illustration_Cirsium_arvense0_cleaned.jpg/330px-Illustration_Cirsium_arvense0_cleaned.jpg", "w": "Ostrożeń polny"}, {"t": "owies", "s": ["owies", "owsa", "owsem", "owsie"], "d": "Zboże jare o dużych wymaganiach wodnych, tolerujące kwaśne gleby. Ziarno używa się głównie jako paszę dla koni i innych zwierząt oraz na płatki.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Oats_closeup.jpg/330px-Oats_closeup.jpg", "w": "Owies zwyczajny"}, {"t": "owies głuchy", "s": ["głuch"], "d": "Dziki, jednoliścienny chwast bardzo podobny do uprawnego owsa, występujący w zbożach. Jego ziarniaki łatwo osypują się i zaśmiecają glebę na lata.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Avena_fatua1.jpg/330px-Avena_fatua1.jpg", "w": "Owies głuchy"}, {"t": "owijarka", "s": ["owijar"], "d": "Maszyna owijająca baloty podsuszonej zielonki folią, aby stworzyć warunki beztlenowe do zakiszania (sianokiszonka)."}, {"t": "ozimina", "s": ["ozim", "ozimin"], "d": "Rośliny ozime to takie, które wysiewa się jesienią; zimują na polu i są zbierane następnego lata (np. pszenica ozima, rzepak ozimy, żyto). Przeciwieństwo roślin jarych, sianych wiosną."}, {"t": "parnik", "s": ["parnik"], "d": "Urządzenie do parowania (gotowania parą) ziemniaków i innych okopowych na paszę; kolumna parnikowa to jego przemysłowa wersja.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Parnik_ustawiony_w_ogrodzie_przy_zagrodzie_-_M%C5%82yny_Strachockie_-_000534n.jpg/330px-Parnik_ustawiony_w_ogrodzie_przy_zagrodzie_-_M%C5%82yny_Strachockie_-_000534n.jpg", "w": "Parnik (urządzenie)"}, {"t": "pasza objętościowa", "s": ["objętościow"], "d": "Pasza o dużej objętości i dużej zawartości włókna: sucha (siano, słoma) lub soczysta (zielonka, kiszonka, okopowe). Podstawa żywienia przeżuwaczy."}, {"t": "pasza treściwa", "s": ["treściw"], "d": "Pasze o dużej koncentracji składników pokarmowych w małej objętości: ziarno zbóż (energetyczne) lub śruty i nasiona strączkowe (białkowe). Przeciwieństwo pasz objętościowych (siano, kiszonka, zielonka)."}, {"t": "paszport bydła", "s": ["paszport"], "d": "Dokument wydawany przez ARiMR dla każdej sztuki bydła, zawierający numer kolczyka, datę urodzenia, rasę i historię przemieszczeń; towarzyszy zwierzęciu przy sprzedaży."}, {"t": "perz", "s": ["perz"], "d": "Uporczywy wieloletni chwast trawiasty rozmnażający się przez podziemne rozłogi. Bardzo trudny do zwalczenia, bo z każdego kawałka rozłogu wyrasta nowa roślina.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Illustration_Elytrigia_repens1.jpg/330px-Illustration_Elytrigia_repens1.jpg", "w": "Perz właściwy"}, {"t": "pietrain", "s": ["pietrain"], "d": "Belgijska rasa świń mięsnych o łaciatym umaszczeniu i bardzo silnie umięśnionych szynkach; używana jako komponent ojcowski.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Berger-markt-ferkel001.jpg/330px-Berger-markt-ferkel001.jpg", "w": "Pietrain"}, {"t": "piórojady", "s": ["piórojad"], "d": "Bezskrzydłe owady pasożytujące na skórze i piórach drobiu; zwalcza się je dezynsekcją kurnika.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9e/Felicola_subrostris.jpg/330px-Felicola_subrostris.jpg", "w": "Wszoły"}, {"t": "plewy", "s": ["plew"], "d": "Łuski okrywające ziarno, oddzielane podczas omłotu; mało wartościowa pasza objętościowa."}, {"t": "pleśń śniegowa", "s": ["pleśni śnieg", "pleśnią śnieg", "pleśń śnieg", "śniegow"], "d": "Choroba grzybowa zbóż ozimych rozwijająca się pod długo zalegającą pokrywą śnieżną na niezamarzniętej glebie. Po roztopach rośliny są pokryte szarobiałą grzybnią i obumierają.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Monographella_nivalis-2013-Brno.jpg/330px-Monographella_nivalis-2013-Brno.jpg", "w": "Pleśń śniegowa"}, {"t": "ploniarka zbożówka", "s": ["ploniark"], "d": "Mała czarna muchówka; jej larwy wgryzają się w liść sercowy (najmłodszy, środkowy) młodych zbóż i kukurydzy, powodując jego żółknięcie i obumieranie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f0/Oscinella_frit.jpg/330px-Oscinella_frit.jpg", "w": "Ploniarka zbożówka"}, {"t": "podeszwa płużna", "s": ["podeszw"], "d": "Zbita, nieprzepuszczalna warstwa gleby powstająca tuż pod głębokością orki wskutek wieloletniego orania na tę samą głębokość. Utrudnia rozwój korzeni; usuwa się ją głęboszowaniem."}, {"t": "podorywka", "s": ["podoryw", "podorywk"], "d": "Płytka orka (8-12 cm) wykonywana zaraz po żniwach jako pierwszy zabieg pożniwny. Przykrywa ścierń, ogranicza parowanie wody i pobudza chwasty do kiełkowania, by je potem zniszczyć."}, {"t": "podłoga rusztowa", "s": ["podłog ażurow", "podłogi ażurow", "rusztow"], "d": "Podłoga z beleczek ze szczelinami, przez które odchody spadają do kanału gnojowego; stosowana zwłaszcza w chlewniach. W teście nazywana podłogą ażurową."}, {"t": "polska czerwona", "s": ["polska czerwon", "polskiej czerwon"], "d": "Stara, rodzima polska rasa bydła o czerwonym umaszczeniu, objęta programem ochrony. Mało wymagająca, o mleku bogatym w białko i tłuszcz."}, {"t": "pomór świń", "s": ["pomor", "pomór"], "d": "Śmiertelna, zaraźliwa choroba wirusowa świń (klasyczny i afrykański pomór świń, ASF). Objawy: gorączka, wybroczyny na skórze, biegunka; zwalczana z urzędu przez wybijanie stad.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Afryka%C5%84ski_pom%C3%B3r_%C5%9Bwi%C5%84_Wiejki_Bielewicze_Gmina_Gr%C3%B3dek.JPG/330px-Afryka%C5%84ski_pom%C3%B3r_%C5%9Bwi%C5%84_Wiejki_Bielewicze_Gmina_Gr%C3%B3dek.JPG", "w": "Afrykański pomór świń"}, {"t": "poplon ścierniskowy", "s": ["poplon"], "d": "Roślina wysiewana latem na ściernisko zaraz po żniwach (np. gorczyca, facelia), zbierana lub przyorywana jesienią tego samego roku. Chroni glebę i dostarcza nawozu zielonego."}, {"t": "powój polny", "s": ["powoju", "powój"], "d": "Wieloletni chwast o wijących się pędach i lejkowatych biało-różowych kwiatach; trudny do zwalczania ze względu na głębokie korzenie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/104_Convolvulus_arvensis.jpg/330px-104_Convolvulus_arvensis.jpg", "w": "Powój polny"}, {"t": "prasa zwijająca", "s": ["pras zwij", "prasa", "prasy", "zwijając"], "d": "Maszyna zbierająca pokos siana, słomy lub podsuszonej trawy i zwijająca go w cylindryczne baloty (bele), które można owinąć folią na sianokiszonkę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/6_1x6_2_Beveiliging_van_stropers_door_middel_van_schermen_van_buizen_met_gaas_be%2C_Bestanddeelnr_256-0855-crop.jpg/330px-6_1x6_2_Beveiliging_van_stropers_door_middel_van_schermen_van_buizen_met_gaas_be%2C_Bestanddeelnr_256-0855-crop.jpg", "w": "Prasa (maszyna rolnicza)"}, {"t": "pryszczyca", "s": ["pryszczyc"], "d": "Bardzo zaraźliwa choroba wirusowa zwierząt parzystokopytnych (bydła, świń, owiec). Pęcherze i rany pojawiają się w jamie gębowej, na racicach i wymieniu."}, {"t": "przedplon", "s": ["przedplon"], "d": "Roślina, która była uprawiana na danym polu w poprzednim roku. Dobry przedplon zostawia glebę w dobrej strukturze i bez chorób groźnych dla rośliny następnej."}, {"t": "przedpłużek", "s": ["przedpłuż"], "d": "Mały dodatkowy korpus zamontowany przed głównym korpusem pługa; zrzuca wierzchnią warstwę z resztkami roślin lub obornikiem na dno bruzdy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/79/Plough_on_the_edge_of_the_field._-_geograph.org.uk_-_185171.jpg/330px-Plough_on_the_edge_of_the_field._-_geograph.org.uk_-_185171.jpg", "w": "Przedpłużek"}, {"t": "przenośnik ślimakowy", "s": ["ślimakow"], "d": "Urządzenie do poziomego transportu ziarna, w którym materiał przesuwa obracająca się śruba (ślimak) w rurze. Do transportu pionowego w silosach służy przenośnik czerpakowy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/94/Combine-harvesting-corn.jpg/330px-Combine-harvesting-corn.jpg", "w": "Przenośnik śrubowy"}, {"t": "przeżuwacze", "s": ["przeżuwacz"], "d": "Zwierzęta o złożonym, czterokomorowym żołądku (żwacz, czepiec, księgi, trawieniec): bydło, owce, kozy. Trawią włókno dzięki bakteriom w żwaczu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Stomach_of_a_beef.png/330px-Stomach_of_a_beef.png", "w": "Żołądek przeżuwacza"}, {"t": "przyczepa samozaładowcza", "s": ["samozaładow", "samozbier"], "d": "Przyczepa z podbieraczem i rotorem, która sama zbiera skoszoną zielonkę lub siano z pokosu i ładuje do skrzyni."}, {"t": "przytulia czepna", "s": ["przytuli"], "d": "Chwast dwuliścienny o czepiających się łodygach pokrytych haczykami, który owija się wokół zbóż i powoduje ich wyleganie. Utrudnia zbiór kombajnem.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Illustration_Galium_aparine0.jpg/330px-Illustration_Galium_aparine0.jpg", "w": "Przytulia czepna"}, {"t": "próchnica", "s": ["próchnic"], "d": "Ciemna, rozłożona materia organiczna w glebie, decydująca o jej żyzności, zdolności zatrzymywania wody i składników pokarmowych.", "img": "https://upload.wikimedia.org/wikipedia/commons/c/cc/Soil_profile.jpg", "w": "Próchnica (humus)"}, {"t": "próg ekonomicznej szkodliwości", "s": ["progów", "próg"], "d": "Takie nasilenie szkodnika lub choroby, przy którym straty plonu przewyższają koszt zabiegu; dopiero po jego przekroczeniu stosuje się opryski chemiczne."}, {"t": "pszenżyto", "s": ["pszenżyt"], "d": "Zboże powstałe ze skrzyżowania pszenicy z żytem. Łączy plenność pszenicy z odpornością żyta na słabsze gleby i mróz; uprawiane głównie na paszę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Triticale.jpg/330px-Triticale.jpg", "w": "Pszenżyto"}, {"t": "pęcina (staw pęcinowy)", "s": ["pęcin"], "d": "Część nogi konia między stawem pęcinowym (nad kopytem, nad stawem koronowym) a kopytem; tu występuje choroba zwana grudą.", "img": "https://upload.wikimedia.org/wikipedia/commons/2/22/Pastern-absorbing-shock.jpg", "w": "Pęcina"}, {"t": "płatności bezpośrednie", "s": ["dopłat", "płatności bezpośredni", "płatnościami bezpośredni"], "d": "Dopłaty z UE wypłacane rolnikom co roku do hektara użytków rolnych (i do zwierząt), pod warunkiem spełniania określonych wymogów."}, {"t": "płodozmian", "s": ["płodozm"], "d": "Zaplanowane na określoną liczbę lat i pól następstwo roślin w gospodarstwie. Zapobiega chorobom, chwastom i wyjałowieniu gleby."}, {"t": "pług", "s": ["pług", "płuż"], "d": "Narzędzie do orki, które odcina i odwraca warstwę gleby (skibę), przykrywając resztki roślin i chwasty. Pług z pogłębiaczem dodatkowo spulchnia warstwę pod skibą.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Old_plough_schema.svg/langpl-330px-Old_plough_schema.svg.png", "w": "Pług"}, {"t": "pług obracalny", "s": ["obracaln", "plug obrotow", "pług obrotow"], "d": "Pług z dwoma zestawami korpusów (prawo- i lewoodkładającymi), który po każdym przejeździe obraca się, dzięki czemu orze bezzagonowo, bez grzbietów i bruzd.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Old_plough_schema.svg/langpl-330px-Old_plough_schema.svg.png", "w": "Pług"}, {"t": "racica", "s": ["racic"], "d": "Rogowe zakończenia palców u bydła, owiec, kóz i świń (odpowiednik kopyta). Wymagają okresowej korekcji, czyli przycinania specjalnymi narzędziami.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/Capreolus_capreolus_cloven_hoof.jpg/330px-Capreolus_capreolus_cloven_hoof.jpg", "w": "Racica"}, {"t": "rak ziemniaka", "s": ["rak ziemn", "raka ziemn"], "d": "Groźna choroba kwarantannowa ziemniaka wywołana przez grzyb, który powoduje narośla (guzowate wyrośla) na bulwach i podstawie łodyg.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Synchytridium_endobioticum.jpg/330px-Synchytridium_endobioticum.jpg", "w": "Rak ziemniaka"}, {"t": "rdza brunatna", "s": ["rdza", "rdzy"], "d": "Choroba grzybowa pszenicy objawiająca się drobnymi rdzawobrunatnymi, pylącymi skupieniami zarodników na liściach. Osłabia roślinę i obniża plon.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Puccinia_recondita_f.sp._tritici_on_Triticum_aestivum%2C_Bruine_roest_op_gewone_tarwe.jpg/330px-Puccinia_recondita_f.sp._tritici_on_Triticum_aestivum%2C_Bruine_roest_op_gewone_tarwe.jpg", "w": "Rdza brunatna pszenicy"}, {"t": "redlica", "s": ["redlic"], "d": "Element siewnika, który wykonuje w glebie bruzdkę i umieszcza w niej nasiona; może być stopkowa, talerzowa lub radełkowa.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Ferguson_GPE_15_seed_drill_coulter_assembly_-_Newark_VTH_2008.jpg/330px-Ferguson_GPE_15_seed_drill_coulter_assembly_-_Newark_VTH_2008.jpg", "w": "Redlica (rolnictwo)"}, {"t": "retardant", "s": ["antywylegacz", "retardant"], "d": "Środek chemiczny (antywylegacz) skracający i wzmacniający źdźbło zbóż, aby rośliny nie wylegały, czyli nie kładły się na ziemi. Stosuje się go wiosną w fazie strzelania w źdźbło."}, {"t": "rizoktonioza", "s": ["rizoktonio"], "d": "Choroba grzybowa ziemniaka objawiająca się czarnymi, przylegającymi do bulw skupiskami grzybni (jak przyschnięta ziemia) oraz gniciem kiełków. Szerzy się przez zakażone sadzeniaki.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Black_scurf_of_potato_rizoktonioza_ziemniaka.jpg/330px-Black_scurf_of_potato_rizoktonioza_ziemniaka.jpg", "w": "Rizoktonioza ziemniaka"}, {"t": "rolnik ryczałtowy", "s": ["ryczałtow", "vat rr"], "d": "Rolnik zwolniony z VAT, który nie wystawia faktur ani nie prowadzi ewidencji; sprzedając produkty podatnikowi VAT otrzymuje od kupującego fakturę VAT RR z 7% zryczałtowanym zwrotem podatku."}, {"t": "rozkruszek mączny", "s": ["rozkrusz"], "d": "Mikroskopijny roztocz żerujący w wilgotnym ziarnie i mące; porażone zboże ma charakterystyczny miodowy (słodkawy) zapach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/Grain_mite_1.JPG/330px-Grain_mite_1.JPG", "w": "Rozkruszek mączny"}, {"t": "rozpylacz", "s": ["dysz ", "dysze", "rozpylacz"], "d": "Dysza opryskiwacza, która rozbija ciecz na krople; różne typy dają różny kształt strumienia (płaski, stożkowy, pasowy). Zatkane dysze dają nierówny strumień."}, {"t": "rozsiewacz nawozów", "s": ["rozsiewacz"], "d": "Maszyna do równomiernego rozrzucania nawozów mineralnych po polu, najczęściej tarczowa (odśrodkowa). Dawkę ustawia się zasuwą według tabeli wysiewu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b3/D%C3%BCngerstreuer.jpg/330px-D%C3%BCngerstreuer.jpg", "w": "Rozsiewacz nawozów"}, {"t": "rośliny motylkowe", "s": ["bobowat", "motylkow", "strączkow"], "d": "Rośliny z rodziny bobowatych (np. groch, łubin, koniczyna, lucerna), które dzięki bakteriom brodawkowym na korzeniach wiążą azot z powietrza. Dzieli się je na grubonasienne (strączkowe) i drobnonasienne.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Naturgeschichte_des_Pflanzenreichs_Tafel_XXXVII.jpg/330px-Naturgeschichte_des_Pflanzenreichs_Tafel_XXXVII.jpg", "w": "Bobowate"}, {"t": "rośliny okopowe", "s": ["okopow"], "d": "Rośliny uprawiane dla podziemnych części, np. ziemniaki i buraki. Wymagają obornika i starannej uprawy, a po nich gleba jest czysta i pulchna."}, {"t": "ruja", "s": ["objawy rui", "objawów rui", "rui", "ruja", "rują", "ruję"], "d": "Okres gotowości samicy do zapłodnienia (u krów co ok. 21 dni), rozpoznawany po zachowaniu i objawach zewnętrznych. Wtedy wykonuje się krycie lub inseminację."}, {"t": "runo", "s": ["runem", "runo"], "d": "Okrywa wełnista owcy; po strzyży zdjęta w całości tworzy jedną zwartą płachtę. Owce typu wełnistego mają długie, gęste runo.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f1/Sheep_eating_grass_edit02.jpg/330px-Sheep_eating_grass_edit02.jpg", "w": "Wełna"}, {"t": "rzepak", "s": ["rzepak"], "d": "Roślina oleista o żółtych kwiatach z rodziny kapustowatych, uprawiana na olej i biopaliwo. Pozostałość po wytłoczeniu oleju (śruta, makuch) jest cenną paszą białkową.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Brassica_napus_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-169.jpg/330px-Brassica_napus_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-169.jpg", "w": "Kapusta rzepak"}, {"t": "rzodkiew świrzepa", "s": ["świrzep"], "d": "Jednoroczny chwast z rodziny kapustowatych o jasnożółtych kwiatach, pospolity w zbożach jarych i okopowych. Przypomina gorczycę polną.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Raphanus_raphanistrum_Sturm40.jpg/330px-Raphanus_raphanistrum_Sturm40.jpg", "w": "Rzodkiew świrzepa"}, {"t": "różyca", "s": ["różyc"], "d": "Bakteryjna choroba zakaźna świń objawiająca się wysoką gorączką i czerwonymi, rombowatymi plamami na skórze. Może przenosić się na ludzi."}, {"t": "sadzeniak", "s": ["sadzeniak"], "d": "Bulwa ziemniaka przeznaczona do sadzenia. Przed sadzeniem często się ją podkiełkowuje w temperaturze 10–15°C."}, {"t": "saletra amonowa", "s": ["saletr"], "d": "Nawóz azotowy (ok. 34% N) zawierający azot w formie amonowej i azotanowej; szybko działa, stosowany pogłównie. Saletrzak to saletra zmieszana z mączką wapienną (ok. 27% N).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d4/Ammonium-nitrate-2D.svg/langpl-330px-Ammonium-nitrate-2D.svg.png", "w": "Azotan amonu"}, {"t": "septorioza", "s": ["septorioz"], "d": "Choroba grzybowa pszenicy powodująca podłużne, brunatne plamy z czarnymi punktami na liściach (septorioza paskowana liści) lub plamy na plewach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Septoria-tritici.jpg/330px-Septoria-tritici.jpg", "w": "Septorioza paskowana liści pszenicy"}, {"t": "seradela", "s": ["seradel"], "d": "Drobnonasienna roślina motylkowata uprawiana na lekkich glebach piaszczystych, często jako wsiewka w żyto. Daje paszę i wzbogaca glebę w azot.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Ornithopus_sativus_101874007.jpg/330px-Ornithopus_sativus_101874007.jpg", "w": "Seradela pastewna"}, {"t": "sianokiszonka", "s": ["sianokisz", "sianokiszonk"], "d": "Kiszonka z podsuszonej (ok. 40–60% suchej masy) trawy lub motylkowatych, zwykle prasowana w baloty i owijana folią; gotowa do skarmiania po ok. 6 tygodniach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Bale_siano_Boron%C3%B3w_2008.jpg/330px-Bale_siano_Boron%C3%B3w_2008.jpg", "w": "Sianokiszonka"}, {"t": "siara", "s": ["siara", "siary", "siarą"], "d": "Pierwsze mleko wydzielane przez samicę po porodzie, bogate w białko i przeciwciała. Cielę lub prosię musi ją wypić w pierwszych godzinach życia, by nabyć odporność.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Colostrum_vs_breastmilk.jpg/330px-Colostrum_vs_breastmilk.jpg", "w": "Siara"}, {"t": "sieczkarnia polowa", "s": ["sieczkarn", "sieczkarni"], "d": "Maszyna ścinająca i rozdrabniająca na sieczkę zielonkę lub całe rośliny kukurydzy przeznaczone na kiszonkę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Feldhaecksler-Mais.jpg/330px-Feldhaecksler-Mais.jpg", "w": "Silosokombajn"}, {"t": "siewnik", "s": ["siewnik"], "d": "Maszyna do wysiewu nasion w równych rzędach na ustaloną głębokość. Siewnik rzędowy sieje zboża ciągłym strumieniem, a punktowy układa pojedyncze nasiona (buraki, kukurydza) w stałych odstępach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Sowing_machine_Nordsten.jpg/330px-Sowing_machine_Nordsten.jpg", "w": "Siewnik"}, {"t": "siewnik punktowy", "s": ["punktow"], "d": "Siewnik wysiewający pojedyncze nasiona w równych odstępach w rzędzie, stosowany do buraków cukrowych i kukurydzy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/Sowing_machine_Nordsten.jpg/330px-Sowing_machine_Nordsten.jpg", "w": "Siewnik"}, {"t": "skrzypionka", "s": ["skrzypionk"], "d": "Niewielki chrząszcz zbóż; jego larwy, pokryte śluzem i odchodami, zeskrobują miękisz liści, zostawiając podłużne białe smugi.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/59/Oulema_melanopus01.jpg/330px-Oulema_melanopus01.jpg", "w": "Skrzypionka zbożowa"}, {"t": "stanówka", "s": ["stanów"], "d": "Okres krycia owiec (rozrodu), w którym tryk (samiec) pokrywa maciorki. Przed stanówką tryka się dokarmia paszą treściwą."}, {"t": "stonka ziemniaczana", "s": ["stonk", "stonka kukurydz", "stonka ziemniacz", "stonki kukurydz", "stonki ziemniacz", "stonkę kukurydz", "stonkę ziemniacz"], "d": "Chrząszcz, którego larwy niszczą korzenie kukurydzy, a dorosłe żerują na znamionach kolb. Szkodnik kwarantannowy, zwalczany głównie przez zmianowanie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/21/Colorado_potato_beetle.jpg/330px-Colorado_potato_beetle.jpg", "w": "Stonka ziemniaczana"}, {"t": "sucha masa", "s": ["sucha mas", "suchej mas", "suchą mas"], "d": "To, co zostaje z paszy po odparowaniu całej wody; podaje się ją w procentach. Pozwala porównywać pasze o różnej wilgotności i obliczać dawki (np. krowa zjada ok. 3,5% masy ciała w suchej masie)."}, {"t": "sucha masa (s.m.)", "s": ["s.m.", "sucha masa", "suchej masy"], "d": "Masa paszy po odjęciu wody; dawki pokarmowe oblicza się w suchej masie (krowa zjada ok. 2,5–3% masy ciała w s.m.)."}, {"t": "sucha zgnilizna kapustnych", "s": ["zgnilizn"], "d": "Choroba grzybowa rzepaku: na liściach pojawiają się jasne plamy z czarnymi punktami, a podstawa łodygi murszeje i roślina wylega."}, {"t": "superfosfat", "s": ["superfosf", "superfosfat"], "d": "Nawóz fosforowy produkowany z fosforytów; superfosfat potrójny zawiera ok. 46% P2O5. Stosuje się go przedsiewnie, bo fosfor słabo przemieszcza się w glebie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/61/Tripelsuperfosfaat_%28triple_phosphate%29.jpg/330px-Tripelsuperfosfaat_%28triple_phosphate%29.jpg", "w": "Superfosfat"}, {"t": "system alkierzowy", "s": ["alkierz"], "d": "System chowu, w którym zwierzęta przebywają stale w budynku (w kojcach), bez wybiegu, z automatami paszowymi i poidłami."}, {"t": "sztuka duża (SD / DJP)", "s": ["sd ", "sd/1"], "d": "Umowna jednostka przeliczeniowa zwierząt (duża jednostka przeliczeniowa, ok. 500 kg żywej masy – jedna krowa); służy do liczenia obsady zwierząt na hektar."}, {"t": "słodyszek rzepakowy", "s": ["słodysz"], "d": "Mały czarny chrząszcz z metalicznym zielono-niebieskim połyskiem (do 2,5 mm), który wygryza pąki kwiatowe rzepaku. Główny szkodnik rzepaku wiosną.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1c/Meligethes_aeneus01.jpg/330px-Meligethes_aeneus01.jpg", "w": "Słodyszek rzepakowiec"}, {"t": "tasznik pospolity", "s": ["tasznik"], "d": "Pospolity chwast o trójkątnych, sercowatych owocach przypominających torebkę. Rośnie na polach i przydrożach przez cały rok.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Capsella_bursa-pastoris_Sturm23.jpg/330px-Capsella_bursa-pastoris_Sturm23.jpg", "w": "Tasznik pospolity"}, {"t": "trawieniec", "s": ["trawieniec", "trawieńc"], "d": "Czwarta komora żołądka przeżuwaczy, jedyna wydzielająca soki trawienne jak zwykły żołądek. U krów mlecznych może dojść do jego przemieszczenia, zwłaszcza po porodzie.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Stomach_of_a_beef.png/330px-Stomach_of_a_beef.png", "w": "Trawieniec"}, {"t": "trojszyk ulec", "s": ["trojszyk"], "d": "Mały rdzawobrunatny chrząszcz żerujący w mące i produktach zbożowych w magazynach. Nadaje im nieprzyjemny zapach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/46/Tribolium.confusum.jpg/330px-Tribolium.confusum.jpg", "w": "Trojszyk ulec"}, {"t": "trwałe użytki zielone", "s": ["użytk zielon", "użytki zielon", "użytków zielon"], "d": "Łąki i pastwiska użytkowane stale od co najmniej 5 lat, nieobjęte płodozmianem. Są podstawą żywienia bydła sianem, zielonką i sianokiszonką."}, {"t": "tryjer", "s": ["tryjer"], "d": "Czyszczalnia nasion z obracającym się cylindrem z wgłębieniami, oddzielająca nasiona według długości (np. połamane ziarniaki, wykę od owsa).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/67/Tryjer_Mayer_and_Company%2C_Szreniawa_%282%29.jpg/330px-Tryjer_Mayer_and_Company%2C_Szreniawa_%282%29.jpg", "w": "Tryjer"}, {"t": "trzypunktowy układ zawieszenia", "s": ["podnośnik", "wieszak", "zawieszan", "łącznik górn"], "d": "Układ z dwoma dolnymi cięgłami i łącznikiem górnym, którym ciągnik podnosi i prowadzi zawieszone narzędzia; sterowany podnośnikiem hydraulicznym.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Ursus_C360_PICT0076.jpg/330px-Ursus_C360_PICT0076.jpg", "w": "Trzypunktowy układ zawieszenia"}, {"t": "typ użytkowy", "s": ["typ użytkow", "typem użytkow", "typu użytkow"], "d": "Grupa zwierząt wyróżniona ze względu na główny kierunek produkcji, np. bydło mleczne, mięsne lub kury nieśne. Zwierzęta różnych typów różnią się budową ciała."}, {"t": "tężyczka pastwiskowa", "s": ["tężyczk"], "d": "Choroba krów spowodowana niedoborem magnezu, zwykle na wiosnę po wypędzeniu na młodą trawę. Objawia się drżeniem mięśni, sztywnym chodem i drgawkami."}, {"t": "użytkowanie smuszkowe", "s": ["smuszk"], "d": "Kierunek użytkowania owiec, w którym pozyskuje się smuszki – skórki jagniąt ubijanych w pierwszych dniach życia (np. owce karakułowe).", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Karakul_sheep_in_Akron_Zoo.jpg/330px-Karakul_sheep_in_Akron_Zoo.jpg", "w": "Karakuł"}, {"t": "wapnowanie", "s": ["cao", "wapna nawozow", "wapnia", "wapniow", "wapnow", "wapnowa"], "d": "Nawożenie gleby wapnem (CaO lub węglanem wapnia) w celu odkwaszenia i poprawy struktury gleby. Nie łączy się go w czasie z obornikiem, bo powoduje straty azotu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/70/Spreading_lime_on_a_Devon_field.jpg/330px-Spreading_lime_on_a_Devon_field.jpg", "w": "Wapnowanie gleby"}, {"t": "warchlak", "s": ["tucznik", "warchlak"], "d": "Młoda świnia po odsadzeniu od lochy, o masie ok. 10-30 kg. Po osiągnięciu ok. 30 kg trafia do tuczu i nazywana jest tucznikiem.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Warchlaki_dzika.JPG/330px-Warchlaki_dzika.JPG", "w": "Warchlak"}, {"t": "wał Campbella", "s": ["campbell"], "d": "Ciężki wał z wąskimi, ostro zakończonymi pierścieniami, który ugniata głębsze warstwy gleby po orce, np. tuż przed siewem.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Campell_roller_A_321.jpg/330px-Campell_roller_A_321.jpg", "w": "Wał Campbella"}, {"t": "wał Crosskill", "s": ["crosskill"], "d": "Wał z zębatymi, luźno osadzonymi pierścieniami, który kruszy bryły i wyrównuje powierzchnię pola.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Rullo_g2.jpg/330px-Rullo_g2.jpg", "w": "Wał (polowy)"}, {"t": "wał strunowy", "s": ["strunow"], "d": "Wał zbudowany z prętów (strun) ułożonych spiralnie, kruszący bryły i lekko zagęszczający glebę; często w agregatach uprawowych.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Rullo_g2.jpg/330px-Rullo_g2.jpg", "w": "Wał (polowy)"}, {"t": "wał uprawowy", "s": ["wał ", "wałem", "wałow", "wałowan", "wału"], "d": "Narzędzie w kształcie walca ugniatające glebę po siewie lub orce. Wał gładki wyrównuje, strunowy i kolczatka kruszą bryły i niszczą skorupę glebową, wał wgłębny (Campbella) dociska warstwę dolną.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/20/Campell_roller_A_321.jpg/330px-Campell_roller_A_321.jpg", "w": "Wał Campbella"}, {"t": "wialnia", "s": ["wialni"], "d": "Maszyna czyszcząca ziarno strumieniem powietrza i sitami, oddzielająca plewy i lekkie zanieczyszczenia.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Wialnia_1.JPG/330px-Wialnia_1.JPG", "w": "Wialnia"}, {"t": "wole", "s": ["wola", "wole"], "d": "Rozszerzenie przełyku u ptaków (np. kury), w którym pokarm jest gromadzony i rozmiękczany przed przejściem do żołądka."}, {"t": "wołek zbożowy", "s": ["wołek", "wołk", "wołka", "wołki"], "d": "Mały ciemnobrunatny chrząszcz z ryjkiem, najgroźniejszy szkodnik magazynowanego ziarna. Larwy rozwijają się wewnątrz ziarniaków.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Sitophilus.granarius.jpg/330px-Sitophilus.granarius.jpg", "w": "Wołek zbożowy"}, {"t": "wrzosówka", "s": ["wrzosów", "wrzosówk"], "d": "Stara polska prymitywna rasa owiec o szarej wełnie mieszanej i czarnej głowie. Bardzo odporna, hodowana na mięso, skóry (kożuchy) i do wypasu nieużytków.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dc/Owca_wrzos%C3%B3wka.jpg/330px-Owca_wrzos%C3%B3wka.jpg", "w": "Owca wrzosówka"}, {"t": "wsiewka", "s": ["wsiewk"], "d": "Roślina wysiewana w tym samym roku w rosnącą już roślinę główną (np. koniczyna w jęczmień), która rozwija się po jej zbiorze. Daje paszę lub nawóz zielony bez dodatkowego roku uprawy."}, {"t": "wyka", "s": ["kosmat", "wyka jar", "wyka ozim", "wyka siewna", "wyki", "wyką"], "d": "Roślina motylkowata drobnonasienna uprawiana na paszę i nasiona, często w mieszankach ze zbożami. Wyka kosmata (ozima) znosi słabe, lekkie gleby.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f3/Vicia_villosa_kz02.jpg/330px-Vicia_villosa_kz02.jpg", "w": "Wyka kosmata"}, {"t": "wyleganie", "s": ["wylegan"], "d": "Przewracanie się i pokładanie źdźbeł zbóż na skutek wiatru, deszczu lub nadmiaru azotu; utrudnia zbiór i obniża jakość ziarna. Zapobiegają mu retardanty.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bf/Wyleganie_%C5%82anu_pszenicy_wywo%C5%82ane_przez_silny_wiatr.jpg/330px-Wyleganie_%C5%82anu_pszenicy_wywo%C5%82ane_przez_silny_wiatr.jpg", "w": "Wyleganie"}, {"t": "wylęganie", "s": ["wylęg"], "d": "Przewracanie się łanu zboża na skutek deszczu, wiatru lub nadmiaru azotu; utrudnia zbiór i obniża plon."}, {"t": "wysmalanie", "s": ["wymak", "wymarz", "wyprz", "wysmal"], "d": "Rodzaje strat zimowych w oziminach: wymarzanie (mróz bez śniegu), wysmalanie (suchy mroźny wiatr), wymakanie (zalanie wodą), wyprzenie (uduszenie pod długo leżącym śniegiem)."}, {"t": "wysłodki buraczane", "s": ["wysłodk"], "d": "Produkt uboczny cukrowni: krajanka buraków po wypłukaniu cukru. Świeże, kiszone lub suszone są energetyczną paszą dla bydła.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/Producing_Your_Sugar-_the_Growth_and_Processing_of_Sugar_Beet_in_Britain%2C_1943_D12619.jpg/330px-Producing_Your_Sugar-_the_Growth_and_Processing_of_Sugar_Beet_in_Britain%2C_1943_D12619.jpg", "w": "Wysłodki"}, {"t": "wzdęcie żwacza", "s": ["wzdęc"], "d": "Nagłe gromadzenie gazów w żwaczu krowy, np. po zjedzeniu dużej ilości młodej koniczyny. Brzuch powiększa się po lewej stronie, zwierzę może się udusić bez szybkiej pomocy."}, {"t": "wóz paszowy", "s": ["wozu paszow", "wóz paszow"], "d": "Przyczepa z mieszalnikiem i nożami, która rozdrabnia i miesza pasze objętościowe z treściwymi (system TMR) i rozdaje je na stół paszowy."}, {"t": "włośnica", "s": ["włośni"], "d": "Choroba pasożytnicza wywołana przez włośnia krętego, małego nicienia żyjącego w mięśniach świń i dzików. Dlatego mięso świń musi być obowiązkowo badane po uboju.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7d/Trichinella_spiralis.jpg/330px-Trichinella_spiralis.jpg", "w": "Włosień kręty"}, {"t": "włóka", "s": ["włók"], "d": "Proste narzędzie (belki lub rama ciągnięta po polu), które wyrównuje powierzchnię i przerywa parowanie gleby; pierwszy zabieg wiosną.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/Fotothek_df_roe-neg_0006278_038_Bauer_mit_Traktor_beim_Pfl%C3%BCgen_eines_Felds.jpg/330px-Fotothek_df_roe-neg_0006278_038_Bauer_mit_Traktor_beim_Pfl%C3%BCgen_eines_Felds.jpg", "w": "Włóka (narzędzie)"}, {"t": "włókowanie", "s": ["włóka", "włóki", "włókow", "włókowan", "włóką"], "d": "Wyrównywanie i zamykanie wierzchniej warstwy gleby wczesną wiosną włóką (belką lub ramą ciągniętą po polu), aby ograniczyć parowanie wody.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/W%C5%82%C3%B3ka%2C_brona_%C5%82%C4%85kowo-polowa_Producent_ATMP.png/330px-W%C5%82%C3%B3ka%2C_brona_%C5%82%C4%85kowo-polowa_Producent_ATMP.png", "w": "Włóka łąkowo-polowa"}, {"t": "zaprawianie nasion", "s": ["zapraw"], "d": "Pokrywanie nasion przed siewem środkiem chemicznym (zaprawą), który chroni kiełkujące rośliny przed chorobami grzybowymi i szkodnikami."}, {"t": "zaraza ziemniaka", "s": ["zaraz", "zaraz ziemniak", "zarazy ziemniak", "zarazą ziemniak"], "d": "Najgroźniejsza choroba ziemniaka, wywołana przez organizm grzybopodobny, rozwijająca się w ciepłej i wilgotnej pogodzie. Powoduje brunatne plamy na liściach i gnicie bulw.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Leptinotarsa_decemlineata_and_Phytophthora_infestans.JPG/330px-Leptinotarsa_decemlineata_and_Phytophthora_infestans.JPG", "w": "Zaraza ziemniaka"}, {"t": "zasada wzajemnej zgodności", "s": ["wzajemna zgodno", "wzajemnej zgodno"], "d": "Cross-compliance – uzależnienie wypłaty płatności bezpośrednich od przestrzegania wymogów ochrony środowiska, dobrostanu zwierząt i dobrej kultury rolnej."}, {"t": "zasuszenie", "s": ["zasusz"], "d": "Przerwanie dojenia krowy na ok. 6-8 tygodni przed kolejnym wycieleniem, aby wymię odpoczęło. Okres laktacji trwa zwykle 305 dni."}, {"t": "zdolność kiełkowania", "s": ["kiełkow"], "d": "Procent czystych nasion, które w sprzyjających warunkach wykiełkują. Razem z czystością daje wartość użytkową nasion."}, {"t": "zgorzel siewek", "s": ["zgorzel"], "d": "Choroba grzybowa kiełkujących roślin – siewki brunatnieją u podstawy i zamierają; sprzyja jej siew w zimną, mokrą glebę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Fusarium_avenaceum_%28Corda%29_Sacc._2250070.jpg/330px-Fusarium_avenaceum_%28Corda%29_Sacc._2250070.jpg", "w": "Zgorzel siewek"}, {"t": "zielonka", "s": ["zielonk"], "d": "Świeżo skoszona roślinność (trawy, lucerna, koniczyna, kukurydza) skarmiana bezpośrednio lub przeznaczona do zakiszenia."}, {"t": "zielononóżka kuropatwiana", "s": ["zielononóż", "zielononóżk"], "d": "Stara polska rasa kur o zielonkawych nogach i upierzeniu przypominającym kuropatwę. Rasa nieśna, odporna, dobra do chowu ekologicznego.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/G%C4%85skowo_-_zielonon%C3%B3zka_kuropatwiana.jpg/330px-G%C4%85skowo_-_zielonon%C3%B3zka_kuropatwiana.jpg", "w": "Zielononóżka kuropatwiana"}, {"t": "zmianowanie", "s": ["płodozmian", "zmianowan"], "d": "Ustalona kolejność uprawy różnych roślin po sobie na tym samym polu, tak by nie wyczerpywać gleby i ograniczać choroby. Zaplanowane na lata dla całego gospodarstwa nazywa się płodozmianem; jego przeciwieństwem jest monokultura."}, {"t": "zoocyd", "s": ["moluskocyd", "rodentycyd", "zoocyd"], "d": "Ogólna nazwa środków zwalczających szkodniki zwierzęce; należą tu m.in. insektycydy (owady), moluskocydy (ślimaki) i rodentycydy (gryzonie)."}, {"t": "złotnicka pstra", "s": ["złotnick"], "d": "Polska rodzima, zagrożona rasa świń o czarno-białym umaszczeniu, hodowana zachowawczo w Wielkopolsce.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/Sus_scrofa_Z%C5%82otnicka_pstra.jpg/330px-Sus_scrofa_Z%C5%82otnicka_pstra.jpg", "w": "Złotnicka pstra"}, {"t": "łubin", "s": ["łubin"], "d": "Roślina bobowata (motylkowa) uprawiana na nasiona paszowe i na zielony nawóz. Dzięki bakteriom na korzeniach wiąże azot z powietrza, dlatego dobrze rośnie na słabych, piaszczystych glebach.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Illustration_Lupinus_luteus1.jpg/330px-Illustration_Lupinus_luteus1.jpg", "w": "Łubin żółty"}, {"t": "ścieżki technologiczne", "s": ["ścież"], "d": "Niewysiane pasy w łanie zboża, po których jeżdżą opryskiwacz i rozsiewacz podczas zabiegów. Ich rozstaw dopasowuje się do szerokości roboczej siewnika i opryskiwacza."}, {"t": "śluzawica", "s": ["śluzawic"], "d": "Naga, wilgotna skóra na nosie bydła (odpowiednik nosa); koło nosowe zakłada się, by chronić ją lub zapobiec ssaniu mleka przez krowę."}, {"t": "śnieć cuchnąca", "s": ["cuchnąc", "śnie", "śnieci", "śnieć"], "d": "Choroba grzybowa pszenicy, w której ziarniaki wypełnia czarna, śmierdząca rybą masa zarodników. Przenosi się z zaprawionym nieprawidłowo ziarnem siewnym.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Tilletia_caries_%28DC.%29_Tul._%26_C._Tul..JPG/330px-Tilletia_caries_%28DC.%29_Tul._%26_C._Tul..JPG", "w": "Śnieć cuchnąca pszenicy"}, {"t": "śruta (śrutowanie)", "s": ["poekstrakc", "śrut"], "d": "Pozostałość po wyekstrahowaniu oleju z nasion rozpuszczalnikiem (np. śruta sojowa, rzepakowa). Najważniejsza pasza białkowa w żywieniu świń i drobiu.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cd/%C5%9Aruta_poekstrakcyjna_rzepakowa.JPG/330px-%C5%9Aruta_poekstrakcyjna_rzepakowa.JPG", "w": "Śruta"}, {"t": "śrutownik", "s": ["rozdrabniacz", "śrutownik"], "d": "Maszyna do rozdrabniania ziarna na śrutę; śrutownik bijakowy rozbija ziarno obracającymi się bijakami, tarczowy rozciera je między tarczami.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Professionele_schrootmolen.jpg/330px-Professionele_schrootmolen.jpg", "w": "Śrutownik"}, {"t": "świnia puławska", "s": ["puławsk"], "d": "Polska rodzima rasa świń o łaciatym, czarno-białym umaszczeniu, objęta programem ochrony zasobów genetycznych.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Pulawska_pig%2C_XXVIII_Krajowa_Wystawa_Zwierz%C4%85t_Hodowlanych_Poznan_%282%29.jpg/330px-Pulawska_pig%2C_XXVIII_Krajowa_Wystawa_Zwierz%C4%85t_Hodowlanych_Poznan_%282%29.jpg", "w": "Puławska (rasa świni)"}, {"t": "żmijka", "s": ["żmijk"], "d": "Czyszczalnia spiralna, w której nasiona okrągłe staczają się szybciej niż płaskie i są w ten sposób rozdzielane."}, {"t": "żwacz", "s": ["żwacz"], "d": "Największa z czterech komór żołądka przeżuwaczy (krowy, owcy), w której bakterie rozkładają celulozę z paszy. Jego wzdęcie to niebezpieczny stan wymagający szybkiej pomocy.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Stomach_of_a_beef.png/330px-Stomach_of_a_beef.png", "w": "Żwacz (przeżuwacze)"}, {"t": "żyto", "s": ["żyta", "żyto"], "d": "Zboże ozime o małych wymaganiach glebowych, uprawiane głównie na słabych, lekkich i kwaśnych glebach. Daje ziarno na mąkę chlebową oraz słomę.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Illustration_Secale_cereale0_clean.jpg/330px-Illustration_Secale_cereale0_clean.jpg", "w": "Żyto zwyczajne"}, {"t": "żółtlica drobnokwiatowa", "s": ["żółtlic"], "d": "Chwast o drobnych żółto-białych kwiatach, pochodzący z Ameryki, masowo występujący w uprawach okopowych i ogrodach. Bardzo szybko wydaje nasiona.", "img": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5f/Galinsoga_parviflora_Sturm16.jpg/330px-Galinsoga_parviflora_Sturm16.jpg", "w": "Żółtlica drobnokwiatowa"}];
